const express = require('express');
const Pool = require('pg-pool');
const bcrypt = require('bcryptjs');
const { OrganizationService } = require('../services/orgService');

const app = express();
app.use(express.json());

const poolManager = {
  pools: new Map(),
  getPool(tenantId) {
    if (!this.pools.has(tenantId)) {
      this.pools.set(
        tenantId,
        new Pool({
          connectionString: `postgresql://admin:${process.env.PGPASSWORD}@pg-main.internal:5432/tenant_${tenantId}`
        })
      );
    }
    return this.pools.get(tenantId);
  }
};

app.post('/api/tenant-admin/:tenantId/create-user', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { tenantId } = req.params;

  // Enforce that caller can only provision users inside their own tenant and must be an admin
  if (req.user.tenantId !== tenantId) {
    return res.status(403).json({ error: 'Access denied: cannot provision users in another tenant database' });
  }

  const isAdmin = await OrganizationService.checkAdminRole(req.user.id, tenantId);
  if (!isAdmin) {
    return res.status(403).json({ error: 'Access denied: administrator privileges required' });
  }

  const { username, email, initialPassword, role } = req.body;
  const pool = poolManager.getPool(tenantId);
  const passwordHash = await bcrypt.hash(initialPassword, 10);

  try {
    const insertResult = await pool.query(
      'INSERT INTO tenant_users (username, email, password_hash, role) VALUES ($1, $2, $3, $4) RETURNING id',
      [username, email, passwordHash, role || 'MEMBER']
    );

    res.status(201).json({ success: true, userId: insertResult.rows[0].id, tenantId });
  } catch (err) {
    res.status(500).json({ error: 'User provisioning failed' });
  }
});

app.listen(9104);
